#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define ROWS 5
#define COLS 6

typedef struct {
    int row[ROWS * COLS];
    int col[ROWS * COLS];
    int head;
    int tail;
} Queue;

static void enqueue(Queue *q, int r, int c) {
    q->row[q->tail] = r;
    q->col[q->tail] = c;
    q->tail++;
}

static void dequeue(Queue *q, int *r, int *c) {
    *r = q->row[q->head];
    *c = q->col[q->head];
    q->head++;
}

static bool inside(int r, int c) {
    return r >= 0 && r < ROWS && c >= 0 && c < COLS;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }
    long sr = strtol(argv[1], NULL, 10);
    long sc = strtol(argv[2], NULL, 10);
    long tr = strtol(argv[3], NULL, 10);
    long tc = strtol(argv[4], NULL, 10);
    if (!inside((int)sr, (int)sc) || !inside((int)tr, (int)tc)) {
        puts("INVALID_CELL");
        return 0;
    }
    bool visited[ROWS][COLS] = { { false } };
    int  dist[ROWS][COLS]    = { { 0 } };
    Queue q = { .head = 0, .tail = 0 };
    enqueue(&q, (int)sr, (int)sc);
    visited[sr][sc] = true;
    dist[sr][sc] = 0;
    const int dr[4] = { -1, 1, 0, 0 };
    const int dc[4] = {  0, 0,-1, 1 };
    bool reached = false;
    while (q.head < q.tail) {
        int r, c;
        dequeue(&q, &r, &c);
        if (r == tr && c == tc) {
            printf("dist=%d\n", dist[r][c]);
            reached = true;
            break;
        }
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (inside(nr, nc) && !visited[nr][nc]) {
                visited[nr][nc] = true;
                dist[nr][nc] = dist[r][c] + 1;
                enqueue(&q, nr, nc);
            }
        }
    }
    if (!reached) {
        puts("UNREACHABLE");
    }
    return 0;
}
